static int classify(const std::string& m) {
    if(m.find("injected")!=std::string::npos || m.find("injection")!=std::string::npos || m.find("dll_hijack")!=std::string::npos || m.find("suspended")!=std::string::npos || m.find("terminated")!=std::string::npos || m.find("pe_injection")!=std::string::npos || m.find("game_instance")!=std::string::npos || m.find("client_checks")!=std::string::npos) return 0;
    if(m.find("ahk")!=std::string::npos || m.find("powershell")!=std::string::npos || m.find("cmd_and_bat")!=std::string::npos || m.find("vbs")!=std::string::npos || m.find("lua")!=std::string::npos || m.find("python")!=std::string::npos || m.find("executed")!=std::string::npos || m.find("files_ran")!=std::string::npos || m.find("modified_extension")!=std::string::npos) return 1;
    if(m.find("prefetch")!=std::string::npos || m.find("fileinfo")!=std::string::npos || m.find("saved_files")!=std::string::npos || m.find("recycle")!=std::string::npos || m.find("asar")!=std::string::npos || m.find("hosts_and")!=std::string::npos || m.find("deleted_exe")!=std::string::npos) return 2;
    if(m.find("registry")!=std::string::npos || m.find("bam")!=std::string::npos || m.find("autoruns")!=std::string::npos || m.find("task_scheduler")!=std::string::npos || m.find("install_time")!=std::string::npos) return 3;
    if(m.find("usb")!=std::string::npos || m.find("disk")!=std::string::npos || m.find("partition")!=std::string::npos || m.find("fat32")!=std::string::npos || m.find("volume")!=std::string::npos || m.find("vhd")!=std::string::npos || m.find("diffdrive")!=std::string::npos) return 4;
    if(m.find("services")!=std::string::npos || m.find("service")!=std::string::npos || m.find("defender")!=std::string::npos || m.find("wmi")!=std::string::npos || m.find("test_signing")!=std::string::npos || m.find("efi")!=std::string::npos || m.find("nvidia")!=std::string::npos || m.find("control_flow")!=std::string::npos || m.find("eventlog")!=std::string::npos) return 5;
    if(m.find("usn")!=std::string::npos || m.find("time_change")!=std::string::npos || m.find("atlas_trace")!=std::string::npos || m.find("crash_dump")!=std::string::npos || m.find("pc_start")!=std::string::npos) return 6;
    if(m.find("discord")!=std::string::npos || m.find("steam")!=std::string::npos || m.find("epic")!=std::string::npos || m.find("r6_alts")!=std::string::npos || m.find("mc_alts")!=std::string::npos || m.find("browser")!=std::string::npos || m.find("vpn")!=std::string::npos || m.find("anydesk")!=std::string::npos || m.find("onedrive")!=std::string::npos) return 7;
    return 8;
}

static std::string lowercase(const char* p) {
    std::string s=p?p:"";
    std::transform(s.begin(),s.end(),s.begin(),[](unsigned char c){return (char)std::tolower(c);});
    return s;
}
static void render(int category) {
    static char query[256]{};
    static bool exactModule=false;
    static int chosenModule=0;
    static std::vector<std::string> modules;
    static std::vector<int> buckets;
    if(modules.empty()){
        std::set<std::string> names;
        for(size_t i=0;i<syncDetectStringCount;++i) names.insert(syncDetectStrings[i].module);
        modules.assign(names.begin(),names.end());
        buckets.reserve(syncDetectStringCount);
        for(size_t i=0;i<syncDetectStringCount;++i)
            buckets.push_back(classify(lowercase(syncDetectStrings[i].module)));
    }
    const int current=category<0?9:category;
    ImGui::TextColored(ImVec4(.35f,.72f,1.f,1.f),"SYNC INTELLIGENCE V8 / %s",category<0?"TODAS AS STRINGS":labels[category]);
    ImGui::TextWrapped("Catalogo de indicadores para auditoria. Strings isoladas e caminhos de DLL nao comprovam alteracao ou malware.");
    ImGui::Separator();
    ImGui::SetNextItemWidth(ImGui::GetContentRegionAvail().x*.58f);
    ImGui::InputTextWithHint("##detectQuery","Pesquisar modulo ou string...",query,sizeof(query));
    ImGui::SameLine();
    if(ImGui::Button("Limpar busca"))query[0]=0;
    ImGui::Checkbox("Filtrar por modulo",&exactModule);
    if(exactModule){
        ImGui::SameLine();
        ImGui::SetNextItemWidth((std::min)(280.f, ImGui::GetContentRegionAvail().x));
        const char* preview=modules.empty()?"":modules[(size_t)chosenModule].c_str();
        if(ImGui::BeginCombo("##moduleSelect",preview)){
            for(size_t i=0;i<modules.size();++i){
                if(ImGui::Selectable(modules[i].c_str(),(int)i==chosenModule))chosenModule=(int)i;
            }
            ImGui::EndCombo();
        }
    }
    // Cache the filtered catalog. Previously every ImGui frame performed
    // thousands of lowercase conversions, allocations and set insertions.
    // Recompute only when the user changes the search or selected category.
    static std::string cachedNeedle;
    static int cachedCategory = -999;
    static int cachedModule = -999;
    static bool cachedExactModule = false;
    static std::vector<int> indices;
    static size_t matchingModules = 0;
    const std::string needle = lowercase(query);
    const int safeModule = modules.empty() ? 0 :
        (std::max)(0, (std::min)(chosenModule, (int)modules.size()-1));
    if (cachedNeedle != needle || cachedCategory != category ||
        cachedModule != safeModule || cachedExactModule != exactModule) {
        cachedNeedle = needle;
        cachedCategory = category;
        cachedModule = safeModule;
        cachedExactModule = exactModule;
        indices.clear();
        indices.reserve(1024);
        std::unordered_set<std::string> foundModules;
        std::unordered_set<std::string> uniqueEntries;
        for (size_t i=0; i<syncDetectStringCount; ++i) {
            if (category >= 0 && buckets[i] != category) continue;
            const auto& item = syncDetectStrings[i];
            if (exactModule && !modules.empty() &&
                modules[(size_t)safeModule] != item.module) continue;
            const std::string mod = lowercase(item.module);
            const std::string val = lowercase(item.value);
            if (!needle.empty() && mod.find(needle)==std::string::npos &&
                val.find(needle)==std::string::npos) continue;
            if (!uniqueEntries.insert(mod+"\n"+val).second) continue;
            indices.push_back((int)i);
            foundModules.insert(mod);
        }
        matchingModules = foundModules.size();
    }
    ImGui::Text("%zu indicadores unicos | %zu modulos | %zu entradas originais",
        indices.size(),matchingModules,syncDetectStringCount);
    if(ImGui::BeginTable("##syncIntelligenceResults",3,ImGuiTableFlags_RowBg|
        ImGuiTableFlags_BordersInnerH|ImGuiTableFlags_Resizable|ImGuiTableFlags_ScrollY,
        ImVec2(0,0))){
        ImGui::TableSetupColumn("Modulo",ImGuiTableColumnFlags_WidthStretch,0.24f);
        ImGui::TableSetupColumn("Categoria",ImGuiTableColumnFlags_WidthStretch,0.24f);
        ImGui::TableSetupColumn("Indicador / literal",ImGuiTableColumnFlags_WidthStretch,0.52f);
        ImGui::TableSetupScrollFreeze(0,1);
        ImGui::TableHeadersRow();
        ImGuiListClipper clipper;
        clipper.Begin((int)indices.size());
        while(clipper.Step()){
            for(int row=clipper.DisplayStart;row<clipper.DisplayEnd;++row){
                int i=indices[(size_t)row];
                const auto& item=syncDetectStrings[i];
                ImGui::TableNextRow();
                ImGui::TableSetColumnIndex(0);ImGui::TextUnformatted(item.module);
                ImGui::TableSetColumnIndex(1);ImGui::TextUnformatted(labels[buckets[(size_t)i]]);
                ImGui::TableSetColumnIndex(2);ImGui::TextUnformatted(item.value);
            }
        }
        ImGui::EndTable();
    }
}

