#include <unordered_map>
#include <unordered_set>
#include <filesystem>
#include <fstream>
#include <algorithm>
#include <commdlg.h>
namespace sync_active_signatures {
struct Match { std::string module, token; int category; };
static std::vector<Match> matches;
static std::string selectedFile, status="Selecione um arquivo local para verificar.";
static bool inspected=false;
static std::string lower(std::string v) {
 for(char &c:v) c=(char)std::tolower((unsigned char)c);
 return v;
}
static std::string utf8(const std::wstring &w) {
 if(w.empty())return {};
 int n=WideCharToMultiByte(CP_UTF8,0,w.c_str(),-1,nullptr,0,nullptr,nullptr);
 if(n<=1)return {};
 std::string r(n,'\0');
 WideCharToMultiByte(CP_UTF8,0,w.c_str(),-1,r.data(),n,nullptr,nullptr);
 r.pop_back();return r;
}
static bool choose() {
 wchar_t filename[32768]={};
 OPENFILENAMEW ofn{};ofn.lStructSize=sizeof(ofn);ofn.lpstrFile=filename;
 ofn.nMaxFile=32768;ofn.lpstrFilter=L"Todos os arquivos\0*.*\0\0";
 ofn.Flags=OFN_FILEMUSTEXIST|OFN_PATHMUSTEXIST|OFN_EXPLORER;
 if(!GetOpenFileNameW(&ofn))return false;
 selectedFile=utf8(filename);return true;
}
static void collect(std::unordered_set<std::string>& observed,const std::string& bytes,bool wide) {
 std::string run;
 const size_t step=wide?2:1;
 for(size_t offset=0;offset<step;++offset){
  run.clear();
  for(size_t i=offset;i+step<=bytes.size();i+=step){
   unsigned char c=(unsigned char)bytes[i];
   bool printable=c>=32&&c<=126&&(!wide||(unsigned char)bytes[i+1]==0);
   if(printable){if(run.size()<256)run.push_back((char)std::tolower(c));}
   else {if(run.size()>=6)observed.insert(run);run.clear();}
  }
  if(run.size()>=6)observed.insert(run);
 }
}
static void scan() {
 matches.clear();inspected=true;
 if(selectedFile.empty()){status="Nenhum arquivo selecionado.";return;}
 std::ifstream f(std::filesystem::u8path(selectedFile),std::ios::binary|std::ios::ate);
 if(!f){status="Nao foi possivel abrir o arquivo.";return;}
 auto size=f.tellg();
 if(size<0||size>8*1024*1024){status="Arquivo excede o limite de 8 MiB.";return;}
 std::string bytes((size_t)size,'\0');
 f.seekg(0);
 if(!f.read(bytes.data(),(std::streamsize)bytes.size())&&!f.eof()){status="Erro de leitura.";return;}
 std::unordered_set<std::string> observed;
 collect(observed,bytes,false);collect(observed,bytes,true);
 std::unordered_set<std::string> seen;
 for(size_t i=0;i<syncDetectStringCount;++i){
  const auto& item=syncDetectStrings[i];
  std::string token=lower(item.value);
  if(token.size()<6||token.size()>256||observed.count(token)==0)continue;
  // Generic runtime/API names are informational, not evidence of a bypass.
  static const std::unordered_set<std::string> genericTokens={
   "kernel32.dll","ntdll.dll","user32.dll","shell32.dll","advapi32.dll",
   "getprocaddress","loadlibrarya","loadlibraryw","virtualalloc",
   "createthread","closehandle","getlasterror","system32\\",
   "microsoft corporation","getmodulehandlea","getmodulehandlew",
   "windows\\temp\\","program files","appdata","username",
   "java.exe","javaw.exe","opengl32.dll","d3d11.dll","dxgi.dll",
   "this program cannot be run in dos mode."
  };
  if(genericTokens.count(token))continue;
  std::string key=std::string(item.module)+"\n"+token;
  if(!seen.insert(key).second)continue;
  matches.push_back({item.module,item.value,sync_detect_browser::classify(lower(item.module))});
  if(matches.size()>=2000)break;
 }
 status="Concluido: "+std::to_string(matches.size())+" correspondencias literais. Nao confirma cheats.";
}
static void render(int category) {
 ImGui::Separator();
 ImGui::TextUnformatted("LOCAL STRING CHECK");
 ImGui::TextDisabled("Leitura sob demanda, sem execucao, exclusao ou envio de arquivos.");
 if(ImGui::Button("Selecionar arquivo"))choose();
 ImGui::SameLine();
 if(ImGui::Button("Analyze file")&&!selectedFile.empty())scan();
 ImGui::TextWrapped("Arquivo: %s",selectedFile.empty()?"(nenhum)":selectedFile.c_str());
 ImGui::TextWrapped("%s",status.c_str());
 ImGui::TextDisabled("Correspondencia exata de strings ASCII/UTF-16; limite 8 MiB.");
 if(!inspected)return;
 if(ImGui::BeginTable("##activeMatches",3,ImGuiTableFlags_RowBg|ImGuiTableFlags_BordersInnerH|ImGuiTableFlags_ScrollY,ImVec2(0,180))){
  ImGui::TableSetupColumn("Modulo",ImGuiTableColumnFlags_WidthStretch,0.25f);ImGui::TableSetupColumn("Categoria",ImGuiTableColumnFlags_WidthStretch,0.25f);ImGui::TableSetupColumn("Indicador",ImGuiTableColumnFlags_WidthStretch,0.5f);
  ImGui::TableHeadersRow();
  for(const auto& m:matches){
   if(category>=0&&m.category!=category)continue;
   ImGui::TableNextRow();
   ImGui::TableSetColumnIndex(0);ImGui::TextUnformatted(m.module.c_str());
   ImGui::TableSetColumnIndex(1);ImGui::TextUnformatted(sync_detect_browser::labels[m.category]);
   ImGui::TableSetColumnIndex(2);ImGui::TextUnformatted(m.token.c_str());
  }
  ImGui::EndTable();
 }
 ImGui::TextWrapped("Aviso: strings comuns produzem falsos positivos. Revise contexto, assinatura e origem.");
}
}

